type matchWhere[Q psql.Filterable] struct {
	cols                matchColumns
	ID                  psql.WhereMod[Q, int64]
	PublicID            psql.WhereMod[Q, uuid.UUID]
	DefinitionVersionID psql.WhereMod[Q, int64]
	Status              psql.WhereMod[Q, enums.MatchStatus]
	StartedAt           psql.WhereMod[Q, time.Time]
	EndedAt             psql.WhereMod[Q, time.Time]
	MinecraftVersion    psql.WhereNullMod[Q, string]
	ServerName          psql.WhereNullMod[Q, string]
	CreatedAt           psql.WhereMod[Q, time.Time]
	R                   matchWhereR[Q]
}

func (matchWhere[Q]) AliasedAs(alias string) matchWhere[Q] {
	return buildMatchWhere[Q](buildMatchColumns(alias))
}

func buildMatchWhere[Q psql.Filterable](cols matchColumns) matchWhere[Q] {
	return matchWhere[Q]{
		cols:                cols,
		ID:                  psql.Where[Q, int64](cols.ID.Expression),
		PublicID:            psql.Where[Q, uuid.UUID](cols.PublicID.Expression),
		DefinitionVersionID: psql.Where[Q, int64](cols.DefinitionVersionID.Expression),
		Status:              psql.Where[Q, enums.MatchStatus](cols.Status.Expression),
		StartedAt:           psql.Where[Q, time.Time](cols.StartedAt.Expression),
		EndedAt:             psql.Where[Q, time.Time](cols.EndedAt.Expression),
		MinecraftVersion:    psql.WhereNull[Q, string](cols.MinecraftVersion.Expression),
		ServerName:          psql.WhereNull[Q, string](cols.ServerName.Expression),
		CreatedAt:           psql.Where[Q, time.Time](cols.CreatedAt.Expression),
		R:                   matchWhereR[Q]{cols: cols},
	}
}

// matchWhereR holds the relationship-based filters of
// matchWhere under the R namespace — mirroring the model's
// R struct — so they cannot collide with column-based filter fields.
type matchWhereR[Q psql.Filterable] struct {
	cols matchColumns
}

// HasMatchPlayers filters parents that have a matching MatchPlayers using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to MatchPlayers).
func (w matchWhereR[Q]) HasMatchPlayers(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := psql.Select(
		sm.Columns(psql.Raw("1")),
		sm.From(MatchPlayers.NameExpr()),
		sm.Where(MatchPlayers.Columns.MatchID.EQ(w.cols.ID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: psql.Exists(q)}
}

