// NULL-tolerant scan buffer for matchScanMapperNullable:
// on a LEFT JOIN miss every column comes back NULL, so each field uses the
// nullable version of the column type even when the column itself is NOT NULL.
type matchPreloadBuf struct {
	ID                  null.Val[int64]
	PublicID            null.Val[uuid.UUID]
	DefinitionVersionID null.Val[int64]
	Status              null.Val[enums.MatchStatus]
	StartedAt           null.Val[time.Time]
	EndedAt             null.Val[time.Time]
	MinecraftVersion    null.Val[string]
	ServerName          null.Val[string]
	CreatedAt           null.Val[time.Time]
}

// matchScanMapperNullable maps the preloaded match
// columns (prefixed with the runtime join alias) without reflection, while
// keeping the LEFT JOIN semantics of the reflection-based mapper: a row whose
// prefixed columns are all NULL yields nil (no child), and NULL values never
// error, they just leave the zero value in the field.
func matchScanMapperNullable(prefix string) scan.Mapper[*Match] {
	return func(ctx context.Context, cols []string) (scan.BeforeFunc, func(any) (*Match, error)) {
		// resolve the column names once per query, not per row
		type target struct {
			idx int
			dst func(b *matchPreloadBuf) any
		}
		targets := make([]target, 0, 9)
		for i, col := range cols {
			name, ok := strings.CutPrefix(col, prefix)
			if !ok {
				continue
			}
			switch name {
			case "id":
				targets = append(targets, target{i, func(b *matchPreloadBuf) any { return &b.ID }})
			case "public_id":
				targets = append(targets, target{i, func(b *matchPreloadBuf) any { return &b.PublicID }})
			case "definition_version_id":
				targets = append(targets, target{i, func(b *matchPreloadBuf) any { return &b.DefinitionVersionID }})
			case "status":
				targets = append(targets, target{i, func(b *matchPreloadBuf) any { return &b.Status }})
			case "started_at":
				targets = append(targets, target{i, func(b *matchPreloadBuf) any { return &b.StartedAt }})
			case "ended_at":
				targets = append(targets, target{i, func(b *matchPreloadBuf) any { return &b.EndedAt }})
			case "minecraft_version":
				targets = append(targets, target{i, func(b *matchPreloadBuf) any { return &b.MinecraftVersion }})
			case "server_name":
				targets = append(targets, target{i, func(b *matchPreloadBuf) any { return &b.ServerName }})
			case "created_at":
				targets = append(targets, target{i, func(b *matchPreloadBuf) any { return &b.CreatedAt }})
			}
		}

		// One scratch buffer reused for every row: before -> scan -> after runs
		// synchronously per row, the scheduled columns are fully overwritten each
		// row, and unselected columns stay zero, so a single buffer preserves the
		// per-row NULL semantics without allocating a buffer per parent row. The
		// returned child (o below) is always freshly allocated, so buf never
		// escapes past the after func.
		buf := new(matchPreloadBuf)
		return func(row *scan.Row) (any, error) {
				for _, t := range targets {
					row.ScheduleScanByIndex(t.idx, t.dst(buf))
				}
				return buf, nil
			}, func(link any) (*Match, error) {
				buf := link.(*matchPreloadBuf)

				// Same rule as the reflection mapper's row validator: the child
				// exists only if at least one of its columns is not NULL. Columns
				// not selected by the query are never scanned and stay invalid,
				// so this check also matches when only a subset is selected.
				if !(buf.ID.IsValue()) &&
					!(buf.PublicID.IsValue()) &&
					!(buf.DefinitionVersionID.IsValue()) &&
					!(buf.Status.IsValue()) &&
					!(buf.StartedAt.IsValue()) &&
					!(buf.EndedAt.IsValue()) &&
					!(buf.MinecraftVersion.IsValue()) &&
					!(buf.ServerName.IsValue()) &&
					!(buf.CreatedAt.IsValue()) {
					return nil, nil
				}

				o := new(Match)
				if buf.ID.IsValue() {
					o.ID = buf.ID.MustGet()
				}
				if buf.PublicID.IsValue() {
					o.PublicID = buf.PublicID.MustGet()
				}
				if buf.DefinitionVersionID.IsValue() {
					o.DefinitionVersionID = buf.DefinitionVersionID.MustGet()
				}
				if buf.Status.IsValue() {
					o.Status = buf.Status.MustGet()
				}
				if buf.StartedAt.IsValue() {
					o.StartedAt = buf.StartedAt.MustGet()
				}
				if buf.EndedAt.IsValue() {
					o.EndedAt = buf.EndedAt.MustGet()
				}
				o.MinecraftVersion = buf.MinecraftVersion
				o.ServerName = buf.ServerName
				if buf.CreatedAt.IsValue() {
					o.CreatedAt = buf.CreatedAt.MustGet()
				}
				return o, nil
			}
	}
}

func (o *Match) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "MatchPlayers":
		rels, ok := retrieved.(MatchPlayerSlice)
		if !ok {
			return fmt.Errorf("match cannot load %T as %q", retrieved, name)
		}

		o.R.MatchPlayers = rels
		o.R.Loaded.MatchPlayers = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Match = o
				rel.R.Loaded.Match = true
			}
		}
		return nil
	case "DefinitionVersion":
		rel, ok := retrieved.(*DefinitionVersion)
		if !ok {
			return fmt.Errorf("match cannot load %T as %q", retrieved, name)
		}

		o.R.DefinitionVersion = rel
		o.R.Loaded.DefinitionVersion = true

		if rel != nil {
			rel.R.Matches = MatchSlice{o}
		}
		return nil
	case "Rounds":
		rels, ok := retrieved.(RoundSlice)
		if !ok {
			return fmt.Errorf("match cannot load %T as %q", retrieved, name)
		}

		o.R.Rounds = rels
		o.R.Loaded.Rounds = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Match = o
				rel.R.Loaded.Match = true
			}
		}
		return nil
	case "StatRecords":
		rels, ok := retrieved.(StatRecordSlice)
		if !ok {
			return fmt.Errorf("match cannot load %T as %q", retrieved, name)
		}

		o.R.StatRecords = rels
		o.R.Loaded.StatRecords = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Match = o
				rel.R.Loaded.Match = true
			}
		}
		return nil
	case "StatValues":
		rels, ok := retrieved.(StatValueSlice)
		if !ok {
			return fmt.Errorf("match cannot load %T as %q", retrieved, name)
		}

		o.R.StatValues = rels
		o.R.Loaded.StatValues = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Match = o
				rel.R.Loaded.Match = true
			}
		}
		return nil
	default:
		return fmt.Errorf("match has no relationship %q", name)
	}
}

type matchPreloader struct {
	DefinitionVersion func(...psql.PreloadOption) psql.Preloader
}

func buildMatchPreloader() matchPreloader {
	return matchPreloader{
		DefinitionVersion: func(opts ...psql.PreloadOption) psql.Preloader {
			return psql.Preload[*DefinitionVersion, DefinitionVersionSlice](psql.PreloadRel{
				Name: "DefinitionVersion",
				Sides: []psql.PreloadSide{
					{
						From:        Matches,
						To:          DefinitionVersions,
						FromColumns: []string{"definition_version_id"},
						ToColumns:   []string{"id"},
					},
				},
			}, DefinitionVersions.Columns.Names(), definitionVersionScanMapperNullable, opts...)
		},
	}
}

