// LoadMatchPlayers loads the match's MatchPlayers into the .R struct
func (o *Match) LoadMatchPlayers(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.MatchPlayers = nil
	o.R.Loaded.MatchPlayers = false

	related, err := o.MatchPlayers(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, rel := range related {
		rel.R.Match = o
		rel.R.Loaded.Match = true
	}

	o.R.MatchPlayers = related
	o.R.Loaded.MatchPlayers = true
	return nil
}

// LoadMatchPlayers loads the match's MatchPlayers into the .R struct
func (os MatchSlice) LoadMatchPlayers(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	matchPlayers, err := os.MatchPlayers(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.MatchPlayers = nil
		o.R.Loaded.MatchPlayers = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	matchByKey := make(map[int64][]*Match, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		matchByKey[o.ID] = append(matchByKey[o.ID], o)
	}

	for _, rel := range matchPlayers {

		owners, ok := matchByKey[rel.MatchID]
		if !ok {
			continue
		}

		for _, o := range owners {

			rel.R.Match = o
			rel.R.Loaded.Match = true

			o.R.MatchPlayers = append(o.R.MatchPlayers, rel)

		}
	}

	return nil
}

// LoadDefinitionVersion loads the match's DefinitionVersion into the .R struct
func (o *Match) LoadDefinitionVersion(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.DefinitionVersion = nil
	o.R.Loaded.DefinitionVersion = false

	related, err := o.DefinitionVersion(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.Matches = MatchSlice{o}

	o.R.DefinitionVersion = related
	o.R.Loaded.DefinitionVersion = true
	return nil
}

// LoadDefinitionVersion loads the match's DefinitionVersion into the .R struct
func (os MatchSlice) LoadDefinitionVersion(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	definitionVersions, err := os.DefinitionVersion(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.DefinitionVersion = nil
		o.R.Loaded.DefinitionVersion = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	matchByKey := make(map[int64][]*Match, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		matchByKey[o.DefinitionVersionID] = append(matchByKey[o.DefinitionVersionID], o)
	}

	for _, rel := range definitionVersions {

		owners, ok := matchByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.DefinitionVersion != nil {
				continue
			}

			rel.R.Matches = append(rel.R.Matches, o)

			o.R.DefinitionVersion = rel

		}
	}

	return nil
}

