// matchC is where relationship counts are stored.
type matchC struct {
	MatchPlayers *int64
	Rounds       *int64
	StatRecords  *int64
	StatValues   *int64
}

// PreloadCount sets a count in the C struct by name
func (o *Match) PreloadCount(name string, count int64) error {
	if o == nil {
		return nil
	}

	switch name {
	case "MatchPlayers":
		o.C.MatchPlayers = &count
	case "Rounds":
		o.C.Rounds = &count
	case "StatRecords":
		o.C.StatRecords = &count
	case "StatValues":
		o.C.StatValues = &count
	}
	return nil
}

type matchCountPreloader struct {
	MatchPlayers func(...bob.Mod[*dialect.SelectQuery]) psql.Preloader
	Rounds       func(...bob.Mod[*dialect.SelectQuery]) psql.Preloader
	StatRecords  func(...bob.Mod[*dialect.SelectQuery]) psql.Preloader
	StatValues   func(...bob.Mod[*dialect.SelectQuery]) psql.Preloader
}

func buildMatchCountPreloader() matchCountPreloader {
	return matchCountPreloader{
		MatchPlayers: func(mods ...bob.Mod[*dialect.SelectQuery]) psql.Preloader {
			return countPreloader[*Match]("MatchPlayers", func(parent string) bob.Expression {
				// Build a correlated subquery: (SELECT COUNT(*) FROM related WHERE fk = parent.pk)
				if parent == "" {
					parent = Matches.Alias()
				}

				subqueryMods := []bob.Mod[*dialect.SelectQuery]{
					sm.Columns(psql.Raw("count(*)")),

					sm.From(MatchPlayers.NameAsExpr()),
					sm.Where(psql.Quote(MatchPlayers.Alias(), "match_id").EQ(psql.Quote(parent, "id"))),
				}
				subqueryMods = append(subqueryMods, mods...)
				return psql.Group(psql.Select(subqueryMods...).Expression)
			})
		},
		Rounds: func(mods ...bob.Mod[*dialect.SelectQuery]) psql.Preloader {
			return countPreloader[*Match]("Rounds", func(parent string) bob.Expression {
				// Build a correlated subquery: (SELECT COUNT(*) FROM related WHERE fk = parent.pk)
				if parent == "" {
					parent = Matches.Alias()
				}

				subqueryMods := []bob.Mod[*dialect.SelectQuery]{
					sm.Columns(psql.Raw("count(*)")),

					sm.From(Rounds.NameAsExpr()),
					sm.Where(psql.Quote(Rounds.Alias(), "match_id").EQ(psql.Quote(parent, "id"))),
				}
				subqueryMods = append(subqueryMods, mods...)
				return psql.Group(psql.Select(subqueryMods...).Expression)
			})
		},
		StatRecords: func(mods ...bob.Mod[*dialect.SelectQuery]) psql.Preloader {
			return countPreloader[*Match]("StatRecords", func(parent string) bob.Expression {
				// Build a correlated subquery: (SELECT COUNT(*) FROM related WHERE fk = parent.pk)
				if parent == "" {
					parent = Matches.Alias()
				}

				subqueryMods := []bob.Mod[*dialect.SelectQuery]{
					sm.Columns(psql.Raw("count(*)")),

					sm.From(StatRecords.NameAsExpr()),
					sm.Where(psql.Quote(StatRecords.Alias(), "match_id").EQ(psql.Quote(parent, "id"))),
				}
				subqueryMods = append(subqueryMods, mods...)
				return psql.Group(psql.Select(subqueryMods...).Expression)
			})
		},
		StatValues: func(mods ...bob.Mod[*dialect.SelectQuery]) psql.Preloader {
			return countPreloader[*Match]("StatValues", func(parent string) bob.Expression {
				// Build a correlated subquery: (SELECT COUNT(*) FROM related WHERE fk = parent.pk)
				if parent == "" {
					parent = Matches.Alias()
				}

				subqueryMods := []bob.Mod[*dialect.SelectQuery]{
					sm.Columns(psql.Raw("count(*)")),

					sm.From(StatValues.NameAsExpr()),
					sm.Where(psql.Quote(StatValues.Alias(), "match_id").EQ(psql.Quote(parent, "id"))),
				}
				subqueryMods = append(subqueryMods, mods...)
				return psql.Group(psql.Select(subqueryMods...).Expression)
			})
		},
	}
}

