type matchJoins[Q dialect.Joinable] struct {
	typ               string
	MatchPlayers      modAs[Q, matchPlayerColumns]
	DefinitionVersion modAs[Q, definitionVersionColumns]
	Rounds            modAs[Q, roundColumns]
	StatRecords       modAs[Q, statRecordColumns]
	StatValues        modAs[Q, statValueColumns]
}

func (j matchJoins[Q]) aliasedAs(alias string) matchJoins[Q] {
	return buildMatchJoins[Q](buildMatchColumns(alias), j.typ)
}

func buildMatchJoins[Q dialect.Joinable](cols matchColumns, typ string) matchJoins[Q] {
	return matchJoins[Q]{
		typ: typ,
		MatchPlayers: modAs[Q, matchPlayerColumns]{
			c: MatchPlayers.Columns,
			f: func(to matchPlayerColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, MatchPlayers.NameExpr().As(to.Alias())).On(
						to.MatchID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		DefinitionVersion: modAs[Q, definitionVersionColumns]{
			c: DefinitionVersions.Columns,
			f: func(to definitionVersionColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, DefinitionVersions.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.DefinitionVersionID),
					))
				}

				return mods
			},
		},
		Rounds: modAs[Q, roundColumns]{
			c: Rounds.Columns,
			f: func(to roundColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Rounds.NameExpr().As(to.Alias())).On(
						to.MatchID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		StatRecords: modAs[Q, statRecordColumns]{
			c: StatRecords.Columns,
			f: func(to statRecordColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, StatRecords.NameExpr().As(to.Alias())).On(
						to.MatchID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		StatValues: modAs[Q, statValueColumns]{
			c: StatValues.Columns,
			f: func(to statValueColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, StatValues.NameExpr().As(to.Alias())).On(
						to.MatchID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
	}
}
